#include <bits/stdc++.h>
using namespace std;
typedef pair<int,int> PI;
typedef long long LL;
#define FI first
#define SE second
#define MP make_pair
#define PB push_back
#define FOR_LOOP(I,N) for(int I=0;I<N;I++)
#define RANGE(I,A,B) for(int I=A;I<B;I++)
#define REVERSE(I,N) for(int I=N-1;I>=0;I--)
#define inputInt(A) scanf("%d",&A)
#define inputPair(A,B) scanf("%d%d",&A,&B)
const int MAX = 31;
const int MOD = 1e9 + 7;
int n;
LL matrix[MAX][MAX];
struct Mat {
    LL t[MAX][MAX];
    void init() {
        FOR_LOOP(i,n) FOR_LOOP(j,n) t[i][j] = (i==j);
    }
    void multiply(Mat& b) {
        LL temp[MAX][MAX];
        FOR_LOOP(i,n) FOR_LOOP(j,n) temp[i][j] = 0;
        FOR_LOOP(i,n) FOR_LOOP(j,n) FOR_LOOP(k,n)
            temp[i][k] += t[i][j] * b.t[j][k] % MOD;
        FOR_LOOP(i,n) FOR_LOOP(j,n) t[i][j] = temp[i][j] % MOD;
    }
};
LL m;
LL powerArr[MAX];
LL answerArr[MAX];
int k;
vector<LL> digitsList;
int main() {
    LL m_input; int k_input;
    scanf("%lld%d", &m_input, &k_input);
    m = m_input; k = k_input;
    while (m) {
        digitsList.PB(m % k);
        m /= k;
    }
    n = k + 1;
    Mat baseMat, identityMat;
    FOR_LOOP(i,k) baseMat.t[i][(i+1)%k] = 1;
    baseMat.t[k][k] = 1;
    identityMat.init();
    FOR_LOOP(i,k+1) {
        baseMat.t[0][i] = 1;
        baseMat.t[i][i] = 1;
    }
    vector<Mat> dMat(digitsList.size());
    dMat[0] = identityMat;
    dMat[0].multiply(baseMat);
    RANGE(i,1,(int)digitsList.size()) {
        dMat[i] = dMat[i-1];
        FOR_LOOP(_,k) dMat[i].multiply(dMat[i]);
        dMat[i].multiply(baseMat);
    }
    FOR_LOOP(i,n) answerArr[i] = 1;
    for (int idx = (int)digitsList.size() - 1; idx >= 0; idx--) {
        FOR_LOOP(_, digitsList[idx]) {
            FOR_LOOP(i,n) powerArr[i] = 0;
            FOR_LOOP(i,n) FOR_LOOP(j,n) powerArr[j] += answerArr[i] * dMat[idx].t[i][j] % MOD;
            FOR_LOOP(i,n) answerArr[i] = powerArr[i] % MOD;
        }
    }
    printf("%lld\n", answerArr[k]);
}
